// ─────────────────────────────────────────────────────────────────────────────
// Phase 3 — Diagnostics
//
// From the §7 Domain Events sections of OP-004, EN-004, EN-031, OP-008, EN-008
// and OP-022. EN-035 §7 publishes nothing of its own; where its prose spells an
// imaging event differently from its owning module (`rad.order.placed`,
// `rad.exam.started`, `pacs.study.received`, `rad.report.drafted|finalised`,
// `rad.critical_finding.raised`), the owner's spelling is what is registered —
// a consumer cannot subscribe to two names for one fact.
//
// Retention splits three ways here, and the split is the point:
//
//   • 2555 days (7 years) for anything that is a clinical, medico-legal or
//     accreditation fact — a result, a report, a dose, a critical-value loop, a
//     QC decision, an EQA score, a competency expiry, an image disclosure. A
//     NABL or AERB assessor asks for these years after the event.
//   • 400–730 days for indicators and operational history that only ever feed a
//     dashboard: TAT breaches, blocked rooms, downtime, unmatched queues.
//   • 30–90 days for interface chatter. EN-004 §5 keeps raw messages 90 days and
//     parsed metadata two years; the *events* about them are the cheap half.
// ─────────────────────────────────────────────────────────────────────────────

